"""
filter.py — Remove JavaScript from an HTML file to mitigate XSS attacks.

Usage:
    python3 filter.py <html-file>

The file is modified in-place.  Legitimate HTML (tables, headers, links,
formatting, normal attributes, etc.) is preserved as much as possible; only
script elements, inline event handlers, javascript: URLsWORK, and other
script-carrying markup are removed.
"""

import re
import sys
from html.parser import HTMLParser

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

# URL schemes that can execute script when a browser follows them.
DANGEROUS_SCHEMES = (
    'javascript:',
    'vbscript:',
    'livescript:',
)

# Attributes whose value is interpreted as a URL.
URL_ATTRIBUTES = frozenset({
    'href', 'src', 'action', 'formaction', 'xlink:href',
    'background', 'dynsrc', 'lowsrc', 'poster',
    'data', 'cite', 'longdesc', 'usemap',
    'classid', 'codebase', 'profile',
})

# A <script ...> ... </script> block, a bare <script .../> or <script>, or a
# stray </script> -- all of these are removed wherever they appear.
SCRIPT_PATTERN = re.compile(
    r'<\s*script\b[^>]*>.*?</\s*script\s*>'
    r'|<\s*script\b[^>]*/?\s*>'
    r'|</\s*script\s*>',
    re.IGNORECASE | re.DOTALL,
)


def _compact_scheme(value):
    """Lowercase and strip whitespace/control characters from a URL value."""
    return re.sub(r'[\s\x00-\x20]+', '', value or '', flags=re.I).lower()


def _scrub_css(css):
    """Remove script-carrying constructs from an inline CSS fragment."""
    css = re.sub(r'expression\s*\([^)]*\)', '', css, flags=re.I)
    css = re.sub(r'url\s*\(\s*["\']?\s*javascript\s*:', 'url(', css, flags=re.I)
    css = re.sub(r'javascript\s*:', '', css, flags=re.I)
    return css


# ---------------------------------------------------------------------------
# Sanitizer
# ---------------------------------------------------------------------------

class Sanitizer(HTMLParser):
    """HTMLParser subclass that re-emits safe HTML only."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.out = []
        self.script_depth = 0   # >0 while inside a removed <script> element
        self.style_depth = 0    # >0 while inside a kept <style> element

    # -- helpers ---------------------------------------------------------

    @staticmethod
    def _quote(value):
        """Escape an attribute value for output inside double quotes."""
        return value.replace('&', '&amp;').replace('"', '&quot;')

    def _clean_attrs(self, attrs):
        """Filter a list of (name, value) attributes, keeping only safe ones."""
        result = []
        for name, value in attrs:
            name_l = name.lower()

            # 1. Inline event handlers: onclick, onload, onerror, ...
            if len(name_l) > 2 and name_l.startswith('on'):
                continue

            # 2. srcdoc can embed a whole HTML document (with script).
            if name_l == 'srcdoc':
                continue

            # 3. URL attributes that use a script-executing scheme.
            if name_l in URL_ATTRIBUTES and value is not None:
                compact = _compact_scheme(value)
                bad = any(compact.startswith(s) for s in DANGEROUS_SCHEMES)
                if (not bad and compact.startswith('data:')
                        and re.search(r'text/(html|xml)|image/svg', compact)):
                    bad = True
                if bad:
                    continue

            # 4. Strip script-looking markup out of attribute values too,
            #    so no '<script>' substring survives anywhere in the output.
            if value is not None:
                value = SCRIPT_PATTERN.sub('', value)

            # 5. Inline styles may smuggle script via CSS expressions.
            if name_l == 'style' and value is not None:
                value = _scrub_css(value)
                if value.strip() == '':
                    continue

            result.append((name, value))
        return result

    def _emit_tag(self, tag, attrs, self_closing):
        parts = ['<', tag]
        for name, value in attrs:
            if value is None:
                parts.append(' ' + name)
            else:
                parts.append(' %s="%s"' % (name, self._quote(value)))
        parts.append('/>' if self_closing else '>')
        self.out.append(''.join(parts))

    # -- parser callbacks -------------------------------------------------

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == 'script':
            self.script_depth += 1
            return                  # remove the tag entirely
        if tag == 'style':
            self.style_depth += 1
        self._emit_tag(tag, self._clean_attrs(attrs), False)

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if tag == 'script':
            return                  # remove self-closing script tag entirely
        if tag == 'style':
            self.style_depth += 1
        self._emit_tag(tag, self._clean_attrs(attrs), True)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == 'script':
            if self.script_depth > 0:
                self.script_depth -= 1
            return                  # never emit a closing script tag
        if self.script_depth > 0:
            return
        if tag == 'style' and self.style_depth > 0:
            self.style_depth -= 1
        self.out.append('</%s>' % tag)

    def handle_data(self, data):
        if self.script_depth > 0:
            return                  # drop all JavaScript source text
        if self.style_depth > 0:
            data = _scrub_css(data)  # keep CSS formatting, drop JS-ish CSS
        if data:
            self.out.append(data)

    def handle_comment(self, data):
        if self.script_depth > 0:
            return
        data = SCRIPT_PATTERN.sub('', data)   # remove script hiding in comments
        self.out.append('<!--%s-->' % data)

    def handle_entityref(self, name):
        if self.script_depth == 0:
            self.out.append('&%s;' % name)

    def handle_charref(self, name):
        if self.script_depth == 0:
            self.out.append('&#%s;' % name)

    def handle_decl(self, decl):
        self.out.append('<!%s>' % decl)

    def unknown_decl(self, data):
        self.out.append('<!%s>' % data)

    def handle_pi(self, data):
        self.out.append('<?%s>' % data)

    def handle_cdata(self, data):
        if self.script_depth == 0:
            self.out.append('<![CDATA[%s]]>' % data)


def sanitize_html(text):
    parser = Sanitizer()
    parser.feed(text)
    parser.close()
    return ''.join(parser.out)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    if len(sys.argv) != 2:
        sys.stderr.write('Usage: python3 filter.py <html-file>\n')
        sys.exit(1)

    path = sys.argv[1]

    # Read the file as bytes and decode with latin-1 so the byte-for-byte
    # round trip is lossless for non-ASCII content.
    with open(path, 'rb') as fh:
        raw = fh.read()

    clean = sanitize_html(raw.decode('latin-1'))

    with open(path, 'wb') as fh:
        fh.write(clean.encode('latin-1'))


if __name__ == '__main__':
    main()
